/**
 * GENERATED by tools/build_layer_atlas.py — do not hand-edit placements.
 *
 * Every wardrobe layer was painted on the same canvas as its base body, then
 * alpha-trimmed by the asset pipeline. The builder restored each layer's
 * position by silhouette fitting, so these rectangles are percentages of the
 * base body box and need no runtime measurement.
 */

import type { BodyId } from './types';

export interface LayerPlacement {
  /** Percent of the base body box. */
  readonly left: number;
  readonly top: number;
  readonly width: number;
  readonly height: number;
}

/** Anatomy landmarks per body, as percentages of the base body box. */
export interface FaceRig {
  readonly eyeY: number;
  readonly browY: number;
  readonly eyeBandTop: number;
  readonly eyeBandHeight: number;
  readonly headTop: number;
  readonly chinY: number;
  readonly headCenterX: number;
  readonly headWidth: number;
  readonly shoulderY: number;
  readonly waistY: number;
  readonly feetY: number;
  readonly bodyCenterX: number;
}

