/** Resolves a manifest key to its hosted URL. */
export function assetUrl(key: string | null | undefined): string | null {
  if (!key) return null;
  return ASSET_URLS[key] ?? null;
}

/** Placement for a layer key, or null for non-composited assets. */
export function placementFor(key: string | null | undefined): LayerPlacement | null {
  if (!key) return null;
  return LAYER_PLACEMENTS[key] ?? null;
}
